"""Original vector artwork for the expanded offline sticker catalogue."""
import math
INK='#26354d'
def shape(tag,**attrs):
 return '<'+tag+' '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())+'/>'
def circle(x,y,r,c,stroke=None):return shape('circle',cx=x,cy=y,r=r,fill=c,stroke=stroke or 'none',stroke_width=3)
def ellipse(x,y,rx,ry,c):return shape('ellipse',cx=x,cy=y,rx=rx,ry=ry,fill=c)
def rect(x,y,w,h,c,rx=5):return shape('rect',x=x,y=y,width=w,height=h,rx=rx,fill=c)
def path(d,c='none',stroke=INK,width=4):return shape('path',d=d,fill=c,stroke=stroke,stroke_width=width,stroke_linecap='round',stroke_linejoin='round')
def line(x1,y1,x2,y2,c=INK,w=4):return path(f'M{x1} {y1}L{x2} {y2}',stroke=c,width=w)
def eyes():return circle(46,61,5,INK)+circle(82,61,5,INK)+path('M54 83Q64 92 74 83',width=3)
def animal(name,color,kind):
 b=''
 if kind=='fish':return path('M29 64L8 42V86Z',color)+ellipse(71,64,41,27,color)+circle(90,55,5,INK)+path('M62 41L74 24L83 44',color)
 if kind=='bird':return ellipse(64,72,39,44,color)+ellipse(64,86,23,29,'#fff8dd')+circle(49,48,5,INK)+circle(79,48,5,INK)+path('M54 62H74L64 76Z','#ffad37')+path('M38 114L47 105M52 114L47 105M76 114L81 105M90 114L81 105',stroke='#e8a137')
 if kind=='rabbit':b=ellipse(44,30,12,28,color)+ellipse(84,30,12,28,color)+ellipse(44,28,6,19,'#ffc3d4')+ellipse(84,28,6,19,'#ffc3d4')
 elif kind in ('cat','fox','wolf'):b=path('M25 52L16 10L53 34M75 34L112 10L103 52',color)
 elif kind=='dog':b=ellipse(23,60,16,38,color)+ellipse(105,60,16,38,color)
 else:b=circle(28,33,19,color)+circle(100,33,19,color)
 b+=ellipse(64,72,44,40,color)+ellipse(64,84,26,20,'#fff3df')+eyes()+path('M57 74H71L64 82Z',INK)
 if name=='Panda':b+=ellipse(45,60,13,16,INK)+ellipse(83,60,13,16,INK)+circle(45,59,4,'white')+circle(83,59,4,'white')
 if kind=='cat':b+=path('M11 73L40 77M11 90L40 84M117 73L88 77M117 90L88 84',width=2)
 if name=='Tiger':b+=path('M39 39L47 52M64 33V47M89 39L81 52M21 72L35 77M107 72L93 77',width=6)
 if name=='Lion':b=circle(64,64,56,'#b97435')+b
 if name=='Unicorn':b=path('M56 40L65 3L76 40','#c499fa')+b
 return b
